  const ensurePanel = () => {
    const { $, window: win, document: doc } = getUiHost();
    if (!$) return null;
    ensureStyles();
    let $panel = $(doc.getElementById(PANEL_ID));
    if ($panel.length) return $panel;

    $(doc.body).append(`
