    }

    /* 动作描写文本 */
    .action-text {
      text-indent: 2em;
      margin-bottom: 1em;
      line-height: 2.2
    }

    /* ===== 神秘商店 ===== */
    .card-merchant {
      padding: 0 !important;
      background: linear-gradient(180deg, #fffef9 0%, #faf6ee 100%);
      border: 1px solid #d4c5a9;
      border-top: 2px solid #d4c5a9;
      border-bottom: 2px solid #d4c5a9;
      border-radius: 8px;
      box-shadow: 0 6px 24px rgba(0, 0, 0, 0.05);
      margin: 1.5em 0;
      position: relative;
      color: #2c2720;
    }

    body[data-theme="dark"] .card-merchant {
      background: linear-gradient(180deg, #2a2218 0%, #1f1a14 100%);
      border: 1px solid #4a3e30;
      border-top: 2px solid #4a3e30;
      border-bottom: 2px solid #4a3e30;
      color: #dfceab;
      box-shadow: 0 6px 24px rgba(0, 0, 0, 0.4);
    }

    .merch-header {
      background: linear-gradient(90deg, rgba(139, 106, 20, 0.06), rgba(200, 164, 94, 0.12), rgba(139, 106, 20, 0.06));
      border-bottom: 1px solid rgba(200, 164, 94, 0.2);
      position: relative;
      z-index: 1;
      border-radius: 8px 8px 0 0;
    }

    .merch-header::after {
      content: '';
      position: absolute;
      inset: 0;
      background: repeating-linear-gradient(90deg, transparent, transparent 8px, rgba(200, 164, 94, 0.03) 8px, rgba(200, 164, 94, 0.03) 9px);
      pointer-events: none;
      border-radius: 8px 8px 0 0;
    }

    body[data-theme="dark"] .merch-header {
      background: linear-gradient(90deg, rgba(200, 164, 94, 0.05), rgba(200, 164, 94, 0.1), rgba(200, 164, 94, 0.05));
    }

    .merch-title-area {
      padding: 16px 20px 4px 20px;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      margin: 0;
      position: relative;
      z-index: 2;
    }

    .merch-title-icon {
      font-size: 20px;
      color: #a37c27;
    }

    body[data-theme="dark"] .merch-title-icon {
      color: #c4ae85;
    }

    .merch-title-text {
      font-family: 'Noto Serif SC', serif;
      font-weight: 700;
      font-size: 1.15rem;
      letter-spacing: 0.2em;
      color: #534533;
    }

    body[data-theme="dark"] .merch-title-text {
      color: #dfceab;
    }

    .merch-title-line {
      flex: 1;
      max-width: 60px;
      height: 1px;
      background: linear-gradient(90deg, transparent, rgba(200, 164, 94, 0.5), transparent);
    }

    body[data-theme="dark"] .merch-title-line {
      background: linear-gradient(90deg, transparent, rgba(200, 164, 94, 0.3), transparent);
    }

    .merch-tabs-container {
      display: flex;
      gap: 4px;
      padding: 8px 16px 0;
      overflow-x: auto;
      flex-wrap: nowrap;
      justify-content: flex-start;
      position: relative;
      z-index: 2;
    }

    .merch-tabs-container::-webkit-scrollbar {
      height: 0;
    }

    .merch-tab {
      padding: 8px 16px;
      font-size: 13px;
      font-weight: bold;
      font-family: var(--font-main);
      color: #8c7b64;
      border: 1px solid transparent;
      border-bottom: none;
      background: transparent;
      cursor: pointer;
      white-space: nowrap;
      transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
      letter-spacing: 1px;
    }

    .merch-tab:hover {
      color: #534533;
      background: rgba(200, 164, 94, 0.08);
      border-radius: 6px 6px 0 0;
    }

    body[data-theme="dark"] .merch-tab {
      color: #8c7b64;
    }

    body[data-theme="dark"] .merch-tab:hover {
      color: #c4ae85;
      background: rgba(200, 164, 94, 0.08);
    }

    .merch-tab.active {
      color: #8b6a14;
      background: transparent;
      border-bottom: 2px solid #8b6a14;
    }

    body[data-theme="dark"] .merch-tab.active {
      color: #d4b06a;
      background: transparent;
      border-bottom: 2px solid #d4b06a;
    }

    .merch-tab.tab-sell {
      margin-left: auto;
      color: #a86262;
    }

    .merch-tab.tab-sell.active {
      border-bottom-color: #a86262;
      color: #8f5353;
    }

    body[data-theme="dark"] .merch-tab.tab-sell {
      color: #a86262;
    }

    body[data-theme="dark"] .merch-tab.tab-sell.active {
      border-bottom-color: #c47676;
      color: #d98686;
    }

    .merch-body {
      padding: 12px 16px 16px;
    }

    .merch-page {
      display: none;
      animation: fadeIn 0.3s ease;
    }

    .merch-page.active {
