      background: rgba(30, 25, 20, 0.6);
      border-color: rgba(180, 160, 120, 0.2);
    }

    body[data-theme="dark"] .merch-item:hover {
      border-color: rgba(180, 160, 120, 0.4);
      background: rgba(40, 35, 30, 0.8);
    }

    body[data-theme="dark"] .merch-item.expanded {
      border-color: rgba(200, 164, 94, 0.6);
      background: rgba(40, 35, 30, 0.9);
      box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
