      background: rgba(200, 164, 94, 0.05);
    }

    body[data-theme="dark"] .merch-item-summary:hover {
      background: rgba(200, 164, 94, 0.1);
    }

    .merch-item-quality-dot {
      width: 4px;
      align-self: stretch;
      border-radius: 2px;
      flex-shrink: 0;
    }

    .merch-item-info {
      flex: 1;
      min-width: 0;
    }

    .merch-item-name {
      font-weight: 700;
      font-size: 15px;
      line-height: 1.4;
      font-family: var(--font-main);
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      color: var(--text-main);
      letter-spacing: 0.5px;
      text-shadow: 0 1px 0 rgba(255, 255, 255, 0.8);
      filter: saturate(0.6) brightness(0.95);
    }

    body[data-theme="dark"] .merch-item-name {
      text-shadow: 0 1px 2px rgba(0, 0, 0, 0.8);
      filter: saturate(0.7) brightness(1.15);
    }

    .merch-item-meta {
