      '芙蕾雅': { color: '#c85b52', avatar: 'https://gitgud.io/Rown/dnf/-/raw/master/%E5%A4%B4%E5%83%8F/' + encodeURIComponent('芙蕾雅') + '.webp', aliases: ['芙蕾雅'], given_name: '芙蕾雅' },
      '卡提希娅': { color: '#3f5f84', avatar: 'https://gitgud.io/Rown/dnf/-/raw/master/%E5%A4%B4%E5%83%8F/' + encodeURIComponent('卡提希娅') + '.webp', aliases: ['卡提希娅'], given_name: '卡提希娅' }
    };

    // 内置角色名单（不可删除）
    const BUILTIN_CHAR_NAMES = Object.keys(CHARACTER_CONFIG);

    // ==================== MVU 接入层 ====================
    const getCore = () => {
      try {
        const win = window.parent || window;
        const $ = window.jQuery || win.jQuery;
        return { window: win, $, getDB: () => win.AutoCardUpdaterAPI || window.AutoCardUpdaterAPI };
      } catch (e) {
        return { window: window, $: window.jQuery, getDB: () => window.AutoCardUpdaterAPI };
      }
    };

    const mvuState = {
      ready: false, mvu: null,
      check: () => {
        const win = getCore().window;
        if (typeof win.Mvu === 'undefined' || typeof win.Mvu.getMvuData !== 'function' || typeof win.Mvu.replaceMvuData !== 'function') {
          mvuState.ready = false; mvuState.mvu = null; return false;
        }
        mvuState.ready = true; mvuState.mvu = win.Mvu; return true;
      }
    };

    const fetchLatestMvuData = () => {
      let finalData = {};
      try {
        if (mvuState.ready || mvuState.check()) {
          const mvuData = mvuState.mvu.getMvuData({ type: 'message', message_id: 'latest' });
          if (mvuData?.stat_data && Object.keys(mvuData.stat_data).length > 0) {
            finalData = mvuData.stat_data;
          } else {
            const chatData = mvuState.mvu.getMvuData({ type: 'chat' });
            if (chatData?.stat_data && Object.keys(chatData.stat_data).length > 0) finalData = chatData.stat_data;
          }
        }
      } catch (e) { console.warn('[正文美化] MVU:', e); }
      return finalData;
    };

    const applyMvuPatches = (patches) => {
      try {
        if (!mvuState.ready && !mvuState.check()) return false;
        const mvuData = mvuState.mvu.getMvuData({ type: 'message', message_id: 'latest' });
        if (!mvuData?.stat_data) return false;
        patches.forEach(patch => {
          const parts = patch.path.split('/').filter(Boolean);
          if (patch.op === 'replace' || patch.op === 'add') {
            let obj = mvuData.stat_data;
            for (let i = 0; i < parts.length - 1; i++) { if (!obj[parts[i]]) obj[parts[i]] = {}; obj = obj[parts[i]]; }
            obj[parts[parts.length - 1]] = patch.value;
          } else if (patch.op === 'remove') {
            let obj = mvuData.stat_data;
            for (let i = 0; i < parts.length - 1; i++) { if (!obj[parts[i]]) return; obj = obj[parts[i]]; }
            delete obj[parts[parts.length - 1]];
          }
        });
        mvuState.mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
        return true;
      } catch (e) { console.warn('[正文美化] MVU patch:', e); return false; }
    };

    // ==================== 自定义角色缓存 (localStorage) ====================
    // 缓存结构: { name, avatar(dataUrl), color }
    // ==================== 商店交易辅助函数（第一阶段：仅读取/发送） ====================
    function merchantParseNumber(input) {
      if (input === null || input === undefined) return 0;
      const txt = String(input).replace(/,/g, '');
      const m = txt.match(/-?\d+(?:\.\d+)?/);
      return m ? Number(m[0]) : 0;
    }

    function merchantFormatCompactChineseNumber(value) {
      const num = Number(value);
      if (!Number.isFinite(num)) return String(value ?? '0');

      const absNum = Math.abs(num);
      const trimDecimals = function (number, digits) {
        return Number(number).toFixed(digits)
          .replace(/(\.\d*?)0+$/, function (_, decimals) { return decimals; })
          .replace(/\.$/, '');
      };
      if (absNum < 1000000) return String(num);

      const sign = num < 0 ? '-' : '';
      const parts = [];
      const push = function (text) { parts.push(String(text)); };
      const pushThousandRemainder = function (remainder) {
        if (remainder <= 0) return;
        push(trimDecimals(remainder / 1000, 2) + '千');
      };

      if (absNum < 100000000) {
        const wan = Math.floor(absNum / 10000);
        const remainder = absNum % 10000;
        push(sign + String(wan) + '万');
        pushThousandRemainder(remainder);
        return parts.join('');
      }

      let remaining = absNum;
      const yi = Math.floor(remaining / 100000000);
      remaining %= 100000000;
      push(sign + String(yi) + '亿');

      const wan = Math.floor(remaining / 10000);
      remaining %= 10000;
      if (wan > 0) push(String(wan) + '万');
      pushThousandRemainder(remaining);

      return parts.join('');
    }

    function merchantFormatDisplayPrice(input) {
      if (input === null || input === undefined) return '0';
      const raw = String(input).replace(/,/g, '').replace(/G/gi, '').trim();
      const match = raw.match(/-?\d+(?:\.\d+)?/);
      if (!match) return raw || '???';
      return merchantFormatCompactChineseNumber(Number(match[0]));
    }

    function merchantGetPlayerGold() {
      const data = fetchLatestMvuData() || {};
      const person = data.人物 || {};
      const bag = person.背包 || {};
      const fromBag = merchantParseNumber(bag.金币);
      if (fromBag > 0) return fromBag;
      return merchantParseNumber(person.金币);
    }

    function merchantIsTrueLike(v) {
      if (v === true || v === 1) return true;
      if (typeof v === 'string') {
        const t = v.trim().toLowerCase();
        return t === 'true' || t === '1' || t === '是' || t === 'yes' || t === 'y';
      }
      return false;
    }

    function merchantNormalizeBagItemType(rawType) {
      const t = String(rawType || '').trim();
      if (t === '任务道具') return '任务物品';
      if (!t) return '杂物';
      if (t.includes('任务')) return '任务物品';
      if (t.includes('唯一')) return '唯一物品';
      if (t.includes('消耗')) return '消耗品';
      if (t.includes('材料')) return '材料';
      if (t.includes('杂')) return '杂物';
      return '杂物';
    }

    function merchantGetSellableEquipments() {
      const data = fetchLatestMvuData() || {};
      const person = data.人物 || {};
      const sellables = [];

      // 装备：兼容 record/object 与 array 两种结构
      const equips = person.装备列表;
      const equipEntries = Array.isArray(equips)
        ? equips.map(function (item, i) { return [String(i), item]; })
        : (equips && typeof equips === 'object' ? Object.entries(equips) : []);

      for (let i = 0; i < equipEntries.length; i++) {
        const pair = equipEntries[i];
        const equipId = pair[0];
        const item = pair[1];
        if (!item || typeof item !== 'object') continue;
        if (!merchantIsTrueLike(item.装备箱)) continue;
        sellables.push({
          __sellKey: 'equip:' + String(equipId),
          __sellKind: '装备',
          名称: item.名称 || equipId,
          品质: item.品质,
          稀有度: item.稀有度,
          类型: item.类型,
          部位: item.部位,
          等级: item.等级,
          数量: 1
        });
      }

      // 背包道具：人物.背包.道具
      const bag = person.背包 || {};
      const bagItems = (bag.道具 && typeof bag.道具 === 'object') ? bag.道具 : {};
      Object.entries(bagItems).forEach(function (pair) {
        const itemName = pair[0];
        const item = pair[1];
        if (!item || typeof item !== 'object') return;
        const qty = merchantParseNumber(item.数量);
        if (qty <= 0) return;
        const itemType = merchantNormalizeBagItemType(item.类型);
        // 出售页仅显示：消耗品/材料/杂物，隐藏任务/唯一
        if (itemType === '任务物品' || itemType === '唯一物品') return;
        if (!['消耗品', '材料', '杂物'].includes(itemType)) return;
        sellables.push({
          __sellKey: 'bag:' + String(itemName),
          __sellKind: '道具',
          名称: itemName,
          品质: item.品质,
          类型: itemType,
          部位: '背包',
          数量: qty
        });
      });

      return sellables;
    }

    function merchantSendMessageToChat(text) {
      const content = (text || '').trim();
      if (!content) return false;
      const win = window.parent || window;
      const doc = win.document || document;
      const textarea = doc.getElementById('send_textarea');
      const sendBtn = doc.getElementById('send_but');
      if (!textarea || !sendBtn) return false;
      textarea.value = content;
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
