        const parts = imgSrc.split('/');
        const categoryIndex = parts.findIndex(p => p === 'NSFW' || p === 'SFW');
        if (categoryIndex === -1 || categoryIndex + 2 >= parts.length) return;

        const category = parts[categoryIndex];
        const character = decodeURIComponent(parts[categoryIndex + 1]);
        const fileNameWithExt = decodeURIComponent(parts[categoryIndex + 2]);
        const fileName = fileNameWithExt.replace(/\.webp$/, '');

        // 提取场景类型（去掉末尾数字）
        const match = fileName.match(/^(.+?)(\d+)$/);
        if (!match) return;

        const sceneType = match[1];
        const maxCount = IMAGE_LISTS[category]?.[character]?.[sceneType];
        if (!maxCount) return;

        // 读取现有缓存
        let unlocked = {};
        try {
          const data = localStorage.getItem('unlocked_cg');
          if (data) unlocked = JSON.parse(data);
        } catch (e) { }

        // 检查是否已存在
        if (!unlocked[character]) unlocked[character] = {};
        if (unlocked[character][sceneType]) return; // 已存在，不重复写入

        // 写入缓存
        unlocked[character][sceneType] = maxCount;
        localStorage.setItem('unlocked_cg', JSON.stringify(unlocked));
