          }
          return `<div class="text-xs font-noto" style="color:#4a3a2a">${rpgEsc(t)}</div>`;
        }).join('');
        remainingHtml = `<div class="mt-2 px-2 py-1.5 rounded" style="background:rgba(0,0,0,0.03);border-left:2px solid rgba(180,160,120,0.3)"><div class="text-xs font-cinzel_body font-bold mb-1" style="color:#a8a090"><i class="fa-solid fa-heart-pulse mr-1"></i>REMAINING</div>${bars}</div>`;
