              <h3 class="font-noto font-bold text-base" style="color:#1a1408;">${char}</h3>
            </div>
            <div class="dice-roll-tag ${critClass}"><i class="fa-solid fa-dice-d20 dice-tag-icon"></i><span class="dice-tag-val">${rollNum === '自动命中' ? '<i class="fa-solid fa-bolt text-sm"></i>' : rollNum}</span></div>
          </div>
        </div>
        <div class="px-4 py-3 space-y-3 relative z-10">
          <div class="flex items-center gap-3"><span class="font-noto font-bold text-sm skill-name-wave">${action}</span><span class="text-sm font-semibold flex items-center gap-1" style="color:#6a5a4a;"><i class="fa-solid fa-arrow-right text-xs" style="opacity:0.5"></i> ${target}</span></div>
          <div class="rounded px-3 py-2 text-xs font-mono font-semibold" style="background:rgba(0,0,0,0.05);color:#2a1a0a;">${rpgDiceIcon(dice)}</div>
          <div class="flex items-center gap-2">
            ${isCrit ? '<span class="text-xs px-2 py-0.5 rounded font-bold badge-glow-danger" style="background:rgba(139,37,0,0.1);border:1px solid rgba(139,37,0,0.25);color:#8b2500;"><i class="fa-solid fa-burst mr-1" style="font-size:9px;"></i>暴击</span>' : result.includes('[命中]') ? '<span class="text-xs px-2 py-0.5 rounded font-bold badge-glow-success" style="background:rgba(45,106,46,0.1);border:1px solid rgba(45,106,46,0.25);color:#2d6a2e;"><i class="fa-solid fa-crosshairs mr-1" style="font-size:9px;"></i>命中</span>' : ''}
            ${dmgNum ? '<span class="font-bold text-base" style="color:#8b2500;">' + dmgNum + '</span>' : ''}
            <span class="text-xs font-semibold" style="color:#4a3a2a;">${result.replace(/.*->\\s*/, '').replace(/\\d+\\s*/, '')}</span>
          </div>
          ${status ? '<div class="status-badge-combat font-semibold"><i class="fa-solid fa-shield-halved mr-1 text-xs"></i>' + status + '</div>' : ''}
          ${remainingHtml}
          ${extraHtml ? `<div class="mt-1 px-1" style="border-top:1px solid rgba(180,160,120,0.15);padding-top:6px;">${extraHtml}</div>` : ''}
        </div>
        ${narration ? `<div class="combat-narration px-4 py-3"><div class="narration-wrap"><i class="fa-solid fa-feather-pointed narr-icon" style="color:#c8a45e;"></i><span class="narration-quote italic font-medium" style="color:#3a2a1a;">${narration}</span></div></div>` : ''}
      </div>`;
    }

    // ===== DICE CHECK CARD RENDERER =====
    function renderRpgDiceCheck(raw, idx) {
      const char = rpgParseField(raw, '角色'), check = rpgParseField(raw, '检定');
      const dice = rpgParseField(raw, '骰运'), result = rpgParseField(raw, '结果'), narration = rpgParseField(raw, '特图的旁白');
      const remaining = rpgParseField(raw, '目标剩余');
      // 提取额外字段
      const checkKnown = ['角色', '检定', '骰运', '结果', '目标剩余', '特图的旁白'];
      const extraFields = rpgExtractExtraFields(raw, checkKnown);
      const extraHtml = rpgRenderExtraFields(extraFields);

      // 判断是否为骰运检定（有骰运字段）还是非骰运结算（无骰运字段）
      const hasDice = !!dice;
      const isSuccess = result.includes('成功') || result.includes('大成功'), isBigSuccess = result.includes('大成功');
      const isFail = result.includes('失败');
      const borderClass = hasDice ? (isSuccess ? 'check-success' : isFail ? 'check-fail' : 'check-neutral') : 'check-neutral';

      // 骰运相关解析（仅骰运检定时使用）
      const rollMatch = dice.match(/判定\[(\d+)\]/), rollNum = rollMatch ? rollMatch[1] : '?';
      const totalMatch = dice.match(/=(\d+)/), totalNum = totalMatch ? totalMatch[1] : '';
      const dcMatch = result.match(/DC\s*(\d+)/), dcNum = dcMatch ? dcMatch[1] : '';
      // 提取 -> 后面的后果描述
      const _ta = document.createElement('textarea'); _ta.innerHTML = result; const decodedResult = _ta.value;
      const descMatch = decodedResult.match(/->\s*(.+)/);
      const resultDesc = descMatch ? descMatch[1].trim() : '';

      // 头部标签和图标根据是否有骰运区分
      const headerLabel = hasDice ? 'Skill Check' : 'Resolution';
      const headerIcon = hasDice ? 'fa-dice-d20' : 'fa-bolt';

      // 骰子点数标签（仅骰运检定显示）
      const diceTagHtml = hasDice
        ? `<div class="dice-roll-tag ${isBigSuccess ? 'crit' : ''}"><i class="fa-solid fa-dice-d20 dice-tag-icon"></i><span class="dice-tag-val">${rollNum}</span></div>`
        : '';

      // 骰运明细行（仅骰运检定显示）
      const diceDetailHtml = hasDice
        ? `<div class="rounded px-3 py-2 text-xs font-mono font-semibold" style="background:rgba(0,0,0,0.05);color:#2a1a0a;">${rpgDiceIcon(dice)}</div>`
        : '';

      // 判定结果行：骰运检定显示成功/失败徽章，非骰运结算直接显示结果文本
      let resultHtml = '';
      if (hasDice) {
        if (isSuccess || isFail) {
          // 明确的成功/失败
          resultHtml = `<div class="flex items-center gap-2">
              <span class="inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded font-bold ${isSuccess ? 'badge-glow-success' : 'badge-glow-danger'}" style="background:${isSuccess ? 'rgba(45,106,46,0.1);border:1px solid rgba(45,106,46,0.25);color:#2d6a2e' : 'rgba(139,37,0,0.1);border:1px solid rgba(139,37,0,0.25);color:#8b2500'}">${isBigSuccess ? '<i class="fa-solid fa-star" style="font-size:9px;"></i> 大成功' : isSuccess ? '<i class="fa-solid fa-check" style="font-size:9px;"></i> 成功' : '<i class="fa-solid fa-xmark" style="font-size:9px;"></i> 失败'}</span>
              ${totalNum ? `<span class="font-bold text-base" style="color:${isSuccess ? '#2d6a2e' : '#8b2500'};">${totalNum}</span>` : ''}
              ${dcNum ? `<span class="text-xs font-semibold" style="color:#4a3a2a;">DC ${dcNum}</span>` : ''}
            </div>`;
        } else {
          // 非成功/失败的其他结果（如杰作、大失败等），展示原文
          const bracketMatch = result.match(/\[([^\]]+)\]/);
          const resultLabel = bracketMatch ? bracketMatch[1] : result.replace(/->.*/, '').replace(/DC\s*\d+/, '').trim();
          resultHtml = `<div class="flex items-center gap-2">
              <span class="inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded font-bold" style="background:rgba(139,122,47,0.1);border:1px solid rgba(139,122,47,0.25);color:#8b7a2f;"><i class="fa-solid fa-scroll" style="font-size:9px;"></i> ${rpgEsc(resultLabel)}</span>
