                <div class="flex items-center gap-2 mb-1"><i class="fa-solid ${headerIcon} text-xs" style="color:#8b7a2f88;"></i><span class="text-xs tracking-wider uppercase font-cinzel_body" style="color:#8b7a2f88;">${headerLabel}</span></div>
