          const incBtn = merchantCreateTagBtn('merchant-tag-mini', '+', 'buy-inc', idx, { 'data-buy-key': it.key, 'data-buy-name': it.name, 'data-buy-price': String(it.price || 0) });
          const removeBtn = merchantCreateTagBtn('merchant-tag-close', '×', 'buy-remove', idx, { 'data-buy-key': it.key, 'data-buy-name': it.name });
          tag.appendChild(name);
          tag.appendChild(qty);
          tag.appendChild(decBtn);
          tag.appendChild(incBtn);
          tag.appendChild(removeBtn);
          buyTags.appendChild(tag);
        }
      }
      buySec.appendChild(buyLabel);
      buySec.appendChild(buyTags);
      content.appendChild(buySec);

      const sellSec = document.createElement('div');
      sellSec.className = 'merchant-cart-section';
      const sellLabel = document.createElement('div');
      sellLabel.className = 'merchant-cart-label';
      sellLabel.textContent = '卖出';
