const 当前场所 = 位置.场所 || '';

// ═══ 地图静态资料（外置） ═══
const __map_data = await (async () => {
  const log = (msg) => { try { console.log(`[沃恩德地图加载] ${msg}`); } catch (_) {} };
  const raw = String(
