    return {};
  }
})();

const mapData = __map_data.mapData || { title: '沃恩德大陆地图', nodes: [], edges: [] };
const loaderData = __map_data.loaderData || {};
const 区域分组 = Array.isArray(loaderData.regionGroups) ? loaderData.regionGroups : [];
const 世界概览 = Array.isArray(loaderData.worldOverview) ? loaderData.worldOverview : [];
const 关键入口 = Array.isArray(loaderData.keyEntrances) ? loaderData.keyEntrances : [];
const keepTypes = new Set(Array.isArray(loaderData.keepTypes) && loaderData.keepTypes.length
  ? loaderData.keepTypes
  : ['ocean', 'temple', 'mountain', 'forest', 'plains', 'wilderness', 'lake', 'city', 'town', 'village', 'castle', 'tower', 'dungeon', 'port', 'camp', 'desert', 'cemetery', 'ruins', 'portal']);
const rawNodes = (mapData.nodes || []).filter(node => node && keepTypes.has(node.type) && !/^(faction_|kingdom_)/.test(String(node.id || '')));
const idToRawNode = Object.fromEntries(rawNodes.map(node => [node.id, node]));

function 归一化(text) {
  return String(text || '')
    .replace(/[\s_]+/g, '')
    .replace(/[.．・‧]/g, '·')
    .replace(/[()（）【】\[\]「」『』]/g, '')
    .toLowerCase();
}

function 拆分别名(name) {
  const source = String(name || '');
  const parts = source
    .split(/[·・‧_()（）【】\[\]「」『』\/]/)
    .map(s => s.trim())
    .filter(Boolean);
  const aliases = [source, ...parts];
  const stripped = source.replace(/\([^)]*\)/g, '').replace(/（[^）]*）/g, '').trim();
  if (stripped && stripped !== source) aliases.push(stripped);
  return _.uniq(aliases.filter(s => s.length >= 2));
}

function 裁剪地名尾缀(text) {
  const source = String(text || '').trim();
  if (!source) return [];

  const patterns = [
    /(边境|边界|地区|地带|一带|附近|周边|沿岸|近郊|郊外)$/u,
    /(村庄|村)$/u
  ];
  const result = [];
  const seen = new Set([归一化(source)]);
  let current = source;

  while (current) {
    let changed = false;
    for (const pattern of patterns) {
      const next = current.replace(pattern, '').trim();
      const norm = 归一化(next);
      if (!next || next === current || norm.length < 2 || seen.has(norm)) continue;
      seen.add(norm);
      result.push(next);
      current = next;
      changed = true;
      break;
    }
    if (!changed) break;
  }

  return result;
}

function 展开文本候选(texts) {
  const result = [];
  const seen = new Set();
  const push = (value) => {
    const text = String(value || '').trim();
    if (!text) return;
    const key = 归一化(text);
    if (!key || seen.has(key)) return;
    seen.add(key);
    result.push(text);
  };

  texts.filter(Boolean).forEach(raw => {
    const source = String(raw || '').trim();
    if (!source) return;
    push(source);

    const parts = source
      .split(/[·・‧／/｜|,，、;；\-—]/)
      .map(s => s.trim())
      .filter(Boolean);

    if (parts.length > 1) {
      parts.slice().reverse().forEach(part => {
        push(part);
        裁剪地名尾缀(part).forEach(push);
      });
    }

    裁剪地名尾缀(source).forEach(push);
  });

  return result;
}

function 提取末级地点候选(texts) {
  const result = [];
