    const key = 归一化(text);
    if (!key || seen.has(key)) return;
    seen.add(key);
    result.push(text);
  };

  texts.filter(Boolean).forEach(raw => {
    const source = String(raw || '').trim();
    if (!source) return;

    const parts = source
      .split(/[·・‧\-—－]/)
      .map(s => s.trim())
      .filter(Boolean);

    if (parts.length < 2) return;

    const last = parts[parts.length - 1];
    push(last);
    裁剪地名尾缀(last).forEach(push);
  });

  return result;
}

function 默认路线名(fromNode, toNode) {
  if (!fromNode || !toNode) return '连通路线';
  if (fromNode.type === 'portal' || toNode.type === 'portal') return '界门通道';
  if (fromNode.type === 'cemetery' || toNode.type === 'cemetery') return '冥界通道';
  if (['ocean', 'port'].includes(fromNode.type) || ['ocean', 'port'].includes(toNode.type)) return '海路';
  if (fromNode.type === 'lake' || toNode.type === 'lake') return '水路';
  if (['mountain', 'forest', 'wilderness', 'desert'].includes(fromNode.type) || ['mountain', 'forest', 'wilderness', 'desert'].includes(toNode.type)) return '山路';
  if (fromNode.type === 'castle' || toNode.type === 'castle') return '要塞通道';
  return '陆路';
}

function 原始边长(fromNode, toNode) {
  const dx = Number(fromNode.x || 0) - Number(toNode.x || 0);
  const dy = Number(fromNode.y || 0) - Number(toNode.y || 0);
  return Math.hypot(dx, dy);
}

const nodes = rawNodes.map((node, index) => ({
