}));
const indexById = Object.fromEntries(nodes.map(node => [node.id, node.index]));
const graphLinks = nodes.map(() => []);

(mapData.edges || []).forEach((edge, edgeIndex) => {
  const fromNode = idToRawNode[edge.source];
  const toNode = idToRawNode[edge.target];
