    const norm = 归一化(raw);
    const exact = 区域分组.find(group => group.places.some(place => 归一化(place) === norm));
    if (exact) return exact;
  }

  for (const raw of arr) {
    const norm = 归一化(raw);
    if (!norm || norm.length < 2) continue;
