}

function 交通参数(label, fromNode, toNode, rawDistance) {
  const text = String(label || '');
  if (/投影|界门|终焉|虚空|入口|秘境|连通/.test(text) && (fromNode.type === 'portal' || toNode.type === 'portal' || /投影/.test(text))) {
    return { mode: '界门', speed: Infinity, scale: 0 };
  }
  if (/浮空|空中|航路/.test(text)) return { mode: '浮空航行', speed: 260, scale: 1.05 };
  if (/海|港|航道|航运|出海|海路|冰海/.test(text) || (是水域节点(fromNode) && 是水域节点(toNode) && (fromNode.type === 'ocean' || toNode.type === 'ocean'))) {
    return { mode: '海船', speed: 180, scale: 0.9 };
  }
  if (/河|湖|渡口|水路|沿岸|入海口|暗河/.test(text) || (是水域节点(fromNode) && 是水域节点(toNode))) {
    return { mode: '水路', speed: 120, scale: 0.75 };
  }
  if (/大道|官道|直道|走廊|高原通道|王室直道/.test(text)) return { mode: '骑乘', speed: 90, scale: 0.85 };
  if (/防线|山道|山路|丘陵|小径|秘径|边境|巡逻|冰原|荒原|矿道|下行|上行|深入|深渊/.test(text) || 是崎岖节点(fromNode) || 是崎岖节点(toNode)) {
    return { mode: rawDistance >= 260 ? '长途跋涉' : '徒步', speed: rawDistance >= 260 ? 50 : 60, scale: 0.7 };
  }
  return { mode: '陆路', speed: 80, scale: 0.8 };
}

function 换算距离(link) {
  const fromNode = 图.nodes[link.from];
  const toNode = 图.nodes[link.to];
  const { scale } = 交通参数(link.label, fromNode, toNode, link.rawDistance);
  if (scale === 0) return 0;
  return Math.max(25, Math.round((link.rawDistance * scale) / 5) * 5);
}

function 格式耗时(km, mode, speed) {
  if (speed === Infinity) return `${mode}瞬达`;
  if (!Number.isFinite(km) || km <= 0) return `${mode}耗时未知`;
  const days = km / speed;
  if (days <= 0.25) return `${mode}约半日`;
  if (days <= 0.75) return `${mode}约1日内`;
  if (days <= 1.25) return `${mode}约1日`;
  const lo = Math.max(1, Math.floor(days));
  const hi = Math.max(lo, Math.ceil(days));
  return lo === hi ? `${mode}约${lo}日` : `${mode}约${lo}~${hi}日`;
}

function 行程(link) {
  const fromNode = 图.nodes[link.from];
  const toNode = 图.nodes[link.to];
  const km = 换算距离(link);
  const { mode, speed } = 交通参数(link.label, fromNode, toNode, link.rawDistance);
  return 格式耗时(km, mode, speed);
}

function 全图交通方式() {
  return '官道/山路/水路/海航/浮空航路/地下入口/冥界通道/元素投影';
}

function 节点简述(node) {
  if (!node) return '未知地点';
  return String(node.brief || `${node.tier || node.type || '未知区域'}节点`);
}

function 相邻路线(node) {
  if (!node) return [];
  return (图.links[node.index] || [])
    .map(link => ({
      to: 图.nodes[link.to].name,
      label: link.label,
      distance: 换算距离(link),
      note: 行程(link)
    }))
    .sort((a, b) => a.distance - b.distance || a.to.localeCompare(b.to, 'zh-Hans-CN'));
}

function 相邻节点简述(node, limit = 8) {
  if (!node) return [];
  return (图.links[node.index] || [])
    .map(link => ({
      node: 图.nodes[link.to],
      via: link.label,
      distance: 换算距离(link)
    }))
    .sort((a, b) => a.distance - b.distance || a.node.name.localeCompare(b.node.name, 'zh-Hans-CN'))
    .slice(0, limit)
    .map(item => ({
      name: item.node.name,
      brief: 节点简述(item.node),
      via: item.via,
      distance: item.distance
    }));
}

function 次邻节点简述(node, limit = 10) {
  if (!node) return [];
  const firstHop = 图.links[node.index] || [];
  const firstSet = new Set(firstHop.map(link => link.to));
  const secondMap = new Map();

  firstHop.forEach(link1 => {
    const midNode = 图.nodes[link1.to];
    (图.links[link1.to] || []).forEach(link2 => {
      if (link2.to === node.index) return;
      if (firstSet.has(link2.to)) return;
      const total = 换算距离(link1) + 换算距离(link2);
      const old = secondMap.get(link2.to);
      if (!old || total < old.distance) {
        secondMap.set(link2.to, {
          name: 图.nodes[link2.to].name,
          brief: 节点简述(图.nodes[link2.to]),
          via: midNode.name,
          distance: total
        });
      }
    });
  });

  return [...secondMap.values()]
    .sort((a, b) => a.distance - b.distance || a.name.localeCompare(b.name, 'zh-Hans-CN'))
    .slice(0, limit);
}

function 最短路(startNode) {
  const dist = new Array(图.nodes.length).fill(Infinity);
  const prev = new Array(图.nodes.length).fill(-1);
  const done = new Array(图.nodes.length).fill(false);
  if (!startNode) return { dist, prev };

  dist[startNode.index] = 0;
  for (let step = 0; step < 图.nodes.length; step++) {
    let pick = -1;
    let best = Infinity;
    for (let i = 0; i < dist.length; i++) {
      if (!done[i] && dist[i] < best) {
        best = dist[i];
        pick = i;
      }
    }
    if (pick < 0) break;
    done[pick] = true;
    for (const link of 图.links[pick] || []) {
      const next = dist[pick] + 换算距离(link);
      if (next < dist[link.to]) {
        dist[link.to] = next;
        prev[link.to] = pick;
      }
    }
  }
  return { dist, prev };
}

function 复原路径(prev, startIndex, endIndex) {
  const path = [];
  for (let cur = endIndex; cur >= 0; cur = prev[cur]) {
    path.push(cur);
    if (cur === startIndex) break;
  }
  if (path[path.length - 1] !== startIndex) return null;
  return path.reverse();
}

function 是参考节点(node) {
  const degree = (图.links[node.index] || []).length;
  return degree >= 3 || ['city', 'castle', 'port', 'town', 'camp', 'temple', 'portal', 'cemetery'].includes(node.type) || /(城|港|要塞|王城|圣殿|王国|帝国|高原|山脉|海|冥界|世界|秘境)$/u.test(node.name);
}

function 路线经由(path) {
  const names = path.slice(1, -1).map(index => 图.nodes[index].name);
  if (!names.length) return '直达';
  if (names.length <= 2) return names.join(' → ');
  return names.slice(0, 2).join(' → ') + ' 等';
}

function 路线耗时(path) {
  let total = 0;
  let mode = '陆路';
  let speed = 80;
  for (let i = 0; i < path.length - 1; i++) {
    const from = path[i];
    const to = path[i + 1];
    const link = (图.links[from] || []).find(item => item.to === to);
    if (!link) continue;
    total += 换算距离(link);
    const params = 交通参数(link.label, 图.nodes[link.from], 图.nodes[link.to], link.rawDistance);
    mode = params.mode;
    speed = params.speed;
  }
  return 格式耗时(total, mode, speed);
}

function 五入(value, step) {
  return Math.max(step, Math.round(value / step) * step);
}

function 路程分档(candidates) {
  const values = candidates.map(route => route.distance).sort((a, b) => a - b);
  if (!values.length) return null;
  const pick = (ratio) => values[Math.max(0, Math.min(values.length - 1, Math.floor((values.length - 1) * ratio)))];
  const near = Math.max(180, 五入(pick(0.3) || 180, 10));
  const cross = Math.max(520, near + 60, 五入(pick(0.65) || 520, 20));
  return { near, cross };
}

function 路线性质(distance, bands) {
  if (!bands) return distance <= 200 ? '近距转场' : distance <= 520 ? '跨区移动' : '远程旅行';
  if (distance <= bands.near) return '近距转场';
  if (distance <= bands.cross) return '跨区移动';
  return '远程旅行';
}

function 远程参考(node, limit = 4) {
  if (!node) return { bands: null, routes: [] };
  const { dist, prev } = 最短路(node);
  const candidates = [];

  图.nodes.forEach(target => {
    if (target.index === node.index) return;
    if (!Number.isFinite(dist[target.index]) || dist[target.index] < 60) return;
    if (!是参考节点(target)) return;
    const path = 复原路径(prev, node.index, target.index);
    if (!path || path.length < 3) return;
    candidates.push({
      name: target.name,
      distance: dist[target.index],
      via: 路线经由(path),
      time: 路线耗时(path)
    });
  });

  const sorted = candidates.sort((a, b) => a.distance - b.distance || a.name.localeCompare(b.name, 'zh-Hans-CN'));
  const bands = 路程分档(sorted);
  const picked = [];
  const used = new Set();

  for (const kind of ['近距转场', '跨区移动', '远程旅行']) {
    const idx = sorted.findIndex((route, routeIndex) => !used.has(routeIndex) && 路线性质(route.distance, bands) === kind);
    if (idx < 0) continue;
    used.add(idx);
    picked.push({ ...sorted[idx], kind });
  }
  for (let i = 0; i < sorted.length && picked.length < limit; i++) {
    if (used.has(i)) continue;
    used.add(i);
    picked.push({ ...sorted[i], kind: 路线性质(sorted[i].distance, bands) });
  }

  return { bands, routes: picked.slice(0, limit) };
}

const 文本候选 = [当前场所, 当前区域, 当前大陆].filter(Boolean);
const 区域候选 = 展开文本候选(文本候选);
