if (!__woende_outline_loader_hide) {
try {
const data = __woende_outline_loader_data;
const 当前世界观 = String(_.get(data, '系统配置.世界观', '') || '').trim();
const 当前剧情变量 = String(_.get(data, '世界信息.世界剧情', '') || '').trim();
const 需要加载大纲 = !(当前世界观 && 当前世界观 !== '琥珀之剑' && !当前剧情变量);

__woende_outline_loader_current_plot = 当前剧情变量;

function 规范剧情名(text) {
  return String(text || '').trim().replace(/[：:]\s*$/, '');
}

function 解析大纲(raw) {
  const lines = String(raw || '').replace(/\r\n/g, '\n').split('\n');
  const chapters = [];
  let currentStage = null;
  let currentChapter = null;
  let currentListField = null;

  for (const rawLine of lines) {
    const line = String(rawLine || '');
    const trimmed = line.trim();
    if (!trimmed) continue;

    const stageMatch = trimmed.match(/^##\s*(.+?)(?:（(.+?)）)?\s*$/);
    if (stageMatch) {
      currentStage = {
        title: stageMatch[1].trim(),
        time: String(stageMatch[2] || '').trim()
      };
      currentChapter = null;
      currentListField = null;
      continue;
    }

    if (!/^\s/.test(line) && /[:：]\s*$/.test(trimmed)) {
      currentChapter = {
        name: 规范剧情名(trimmed),
        stageTitle: currentStage ? currentStage.title : '',
        time: currentStage ? currentStage.time : '',
        fields: []
      };
      chapters.push(currentChapter);
      currentListField = null;
      continue;
    }

    const listFieldMatch = line.match(/^\s{2,}([^：:]+)[：:]\s*$/);
    if (listFieldMatch && currentChapter) {
      currentListField = {
        key: listFieldMatch[1].trim(),
        value: []
      };
      currentChapter.fields.push(currentListField);
      continue;
    }

    const listItemMatch = line.match(/^\s{4,}-\s*(.+)\s*$/);
    if (listItemMatch && currentListField && Array.isArray(currentListField.value)) {
      currentListField.value.push(listItemMatch[1].trim());
      continue;
    }

    const fieldMatch = line.match(/^\s{2,}([^：:]+)[：:]\s*(.+)\s*$/);
    if (fieldMatch && currentChapter) {
      currentChapter.fields.push({
        key: fieldMatch[1].trim(),
        value: fieldMatch[2].trim()
      });
      currentListField = null;
    }
  }

  return chapters;
}

if (需要加载大纲) {
  const __outline_raw = String(
    await getWorldInfo('沃恩德大纲')
    || await getWorldInfo('琥珀之剑/琥珀之剑大纲')
    || ''
  );

  if (!__outline_raw.trim()) {
    try { console.log('[沃恩德大纲加载] 未找到世界书：沃恩德大纲'); } catch (_) {}
  } else {
    const chapters = 解析大纲(__outline_raw);
    if (!chapters.length) {
      try { console.log('[沃恩德大纲加载] 大纲解析后没有章节'); } catch (_) {}
    } else {
      const firstChapter = chapters[0];
      const currentChapter = chapters.find(ch => ch.name === 当前剧情变量) || firstChapter;
      const currentIndex = Math.max(0, chapters.findIndex(ch => ch.name === currentChapter.name));
      const nextChapter = chapters[currentIndex + 1] || null;

      __woende_outline_loader_current_chapter = currentChapter;
      __woende_outline_loader_current_year = currentChapter.time || currentChapter.stageTitle || '未知';
      __woende_outline_loader_next_plot = nextChapter ? nextChapter.name : '无（已到当前已知大纲末段）';
      __woende_outline_loader_render = true;
    }
  }
}
} catch (e) {
  try {
    console.log(`[沃恩德大纲加载] 执行失败: ${e && e.stack ? e.stack : e}`);
  } catch (_) {}
}
}
